import type { FlowValueType, OutputsWithDotwalk } from './FlowTypes'
import type { FlowConfigProps, FlowVariableProps, FlowStageProps } from './Subflow'
import type { FlowStageConfig } from './flow-logic/stage'
import type { TriggerInstance } from './TriggerDefinition'

/** @interface */
export type FlowDefinition<
    V extends Record<string, FlowValueType>,
    S extends { [key: string]: FlowStageConfig } = {},
> = Now.Internal.WithID<FlowConfigProps & FlowVariableProps<V> & FlowStageProps<S> & Now.Internal.OverrideProperties>

/** @interface */
export type FlowBodyParams<I, V, S extends { [key: string]: FlowStageConfig } = {}> = {
    trigger: I
    flowVariables: V
    /** Named stages declared in the flow config. Activate a stage via `wfa.stage(params.stages.myStage)`. */
    stages: S
}

/**
 * Creates a Flow record (`sys_hub_flow`) that defines a series of actions to execute when triggered.
 * @interface
 * @group Flow
 * @param config Flow configuration — name, description, priority, variables, stages, and protectionPolicy settings.
 * @param triggerInstance The trigger that starts this flow, created by calling `wfa.trigger`.
 * @param body The flow body function. Receives `params` containing `trigger`, `flowVariables`,
 * and `stages` (any flow-level stages declared in `config`).
 */
export declare function Flow<
    const F extends ReturnType<TriggerInstance>,
    V extends Record<string, FlowValueType>,
    const S extends { [key: string]: FlowStageConfig } = {},
>(
    config: FlowDefinition<V, S>,
    triggerInstance: F | undefined,
    body?: (params: FlowBodyParams<F, OutputsWithDotwalk<V>, S>) => void
): FlowDefinition<V, S>
